<?php
// index.php
session_start();

if (!isset($_SESSION['user'])) {
    header('Location: login.php');
    exit;
}

if (isset($_GET['logout'])) {
    session_destroy();
    header('Location: login.php');
    exit;
}

$postsFile = 'posts.json';
$posts = json_decode(file_get_contents($postsFile), true) ?: [];
$posts = is_array($posts) ? $posts : [];
