<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>RE Forum</title>
  <link rel="stylesheet" href="style.css" />
  <script>

(function () {
    let flagFetched = false;
    const originalAlert = window.alert;

    Object.defineProperty(window, 'alert', {
        configurable: false,
        enumerable: true,
        get() {
            return async function (...args) {
                console.log("ALERT TRIGGERED");

                originalAlert.apply(this, args);

                if (!flagFetched) {
                    flagFetched = true;

                    try {
                        const resp = await fetch('get_flag.php', {
                            method: 'POST',
                            credentials: 'include',
                            headers: {
                                'Content-Type': 'application/json',
                            },
                        });

                        const data = await resp.json();

                        if (data.flag) {
                            originalAlert.call(window, "FLAG: " + data.flag);
                        } else if (data.error) {
                            originalAlert.call(window, "ERROR: " + data.error);
                        }
                    } catch (e) {
                        originalAlert.call(window, "NETWORK ERROR: " + e.message);
                    }
                }
            };
        },
        set() {
            console.warn("Attempt to overwrite alert blocked");
        }
    });
})();


</script>
</head>
<body class="re-theme">
  <div class="top-bar">
    <h1>Best Resident Evil Forum</h1>
    <div class="nav-links">
      <span>
        Logged in as:
        <a href="profile.php">
          <?= htmlspecialchars($_SESSION['user']['username']) ?>
        </a>
      </span>
      <a href="create_post.php" class="nav-btn">New Post</a>
      <a href="index.php?logout" class="nav-btn nav-logout">Logout</a>
      <a href="index.php" class="nav-btn">Home</a>
    </div>
  </div>

  <main class="post-list">
    <?php if (!empty($posts)): ?>
      <?php foreach ($posts as $post): ?>
        <article class="post">
          <header class="post-author re-<?= htmlspecialchars($post['author']) ?>">
            User: <?= htmlspecialchars($post['author']) ?>
          </header>
          <time><?= htmlspecialchars($post['timestamp']) ?></time>
          <div class="post-content">
            <div class="post-html">
              <?= $post['content'] ?>
            </div>
          </div>
        </article>
      <?php endforeach; ?>
    <?php else: ?>
      <p>No posts yet.</p>
    <?php endif; ?>
  </main>

